/* ============================================================
   Matching Results
   ============================================================ */

.page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.header-with-icon {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--teal-600);
}

/* ---------- Intake summary ---------- */
.intake-summary {
  padding: 18px 20px;
  margin-bottom: 16px;
}

.summary-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.summary-head-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.summary-badge {
  width: 40px;
  height: 40px;
  background: var(--blue-50);
  color: var(--blue-600);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.summary-title {
  display: block;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text-primary);
}

.summary-sub {
  display: block;
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

@media (min-width: 768px) {
  .summary-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.summary-field {
  display: flex;
  flex-direction: column;
  gap: 3px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  min-width: 0;
}

.sf-label {
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
}

.sf-value {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- Formula callout ---------- */
.formula-callout {
  display: flex;
  align-items: center;
  gap: 10px;
  background: linear-gradient(135deg, var(--teal-50), var(--blue-50));
  border: 1px solid var(--teal-100);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  margin-bottom: 16px;
  color: var(--teal-700);
}

.formula-text {
  font-size: 0.8rem;
  color: var(--teal-800);

  strong {
    font-weight: 700;
    color: var(--teal-600);
  }
}

/* ---------- Candidate list ---------- */
.candidate-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-bottom: 20px;
}

.candidate-card {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
  padding: 18px;
  cursor: pointer;
  border: 2px solid transparent;
  transition: all var(--transition-fast);
  position: relative;

  &:hover {
    box-shadow: var(--shadow-md);
  }

  &.selected {
    border-color: var(--teal-500);
    box-shadow: 0 0 0 3px var(--teal-100);
  }
}

@media (min-width: 900px) {
  .candidate-card {
    grid-template-columns: auto auto 1fr 320px;
    align-items: center;
    gap: 20px;
  }
}

/* Selection radio */
.candidate-radio {
  display: none;
}

@media (min-width: 900px) {
  .candidate-radio {
    display: flex;
  }
}

.radio-outer {
  width: 22px;
  height: 22px;
  border: 2px solid var(--gray-300);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition-fast);

  &.checked {
    border-color: var(--teal-600);
  }
}

.radio-inner {
  width: 12px;
  height: 12px;
  background: var(--teal-600);
  border-radius: var(--radius-full);
}

/* Rank column */
.rank-col {
  display: flex;
  align-items: center;
  gap: 10px;
}

@media (min-width: 900px) {
  .rank-col {
    flex-direction: column;
    gap: 4px;
  }
}

.rank-badge {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  color: var(--gray-600);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.95rem;
  font-weight: 800;
  flex-shrink: 0;

  &.rank-1 {
    background: linear-gradient(135deg, var(--amber-400), var(--amber-600));
    color: white;
    box-shadow: 0 4px 10px rgba(245, 158, 11, 0.3);
  }
}

.rank-label {
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

/* Candidate info */
.candidate-info {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.candidate-head {
  display: flex;
  align-items: center;
  gap: 12px;
}

.cg-avatar {
  width: 46px;
  height: 46px;
  border-radius: var(--radius-full);
  background: linear-gradient(135deg, var(--teal-400), var(--teal-700));
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  font-weight: 700;
  flex-shrink: 0;
}

.cg-details {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.cg-name {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-primary);
}

.cg-id {
  font-size: 0.72rem;
  color: var(--text-muted);
}

.cert-list {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.cert-tag {
  font-size: 0.68rem;
  font-weight: 600;
  padding: 3px 8px;
  background: var(--teal-50);
  color: var(--teal-700);
  border-radius: var(--radius-sm);
}

.candidate-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.meta-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-secondary);
}

/* Score column */
.score-col {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-top: 14px;
  border-top: 1px solid var(--gray-100);
}

@media (min-width: 900px) {
  .score-col {
    padding-top: 0;
    padding-left: 20px;
    border-top: none;
    border-left: 1px solid var(--gray-100);
  }
}

.total-score {
  display: flex;
  align-items: baseline;
  gap: 3px;

  .score-num {
    font-size: 2rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    line-height: 1;
  }

  .score-denom {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--text-muted);
  }

  &.score-excellent .score-num { color: var(--green-600); }
  &.score-good .score-num      { color: var(--teal-600); }
  &.score-fair .score-num      { color: var(--amber-600); }
  &.score-low .score-num       { color: var(--red-600); }
}

.breakdown {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.breakdown-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.breakdown-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.breakdown-key {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.breakdown-pts {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--text-primary);

  small {
    font-weight: 500;
    color: var(--text-muted);
    font-size: 0.65rem;
  }
}

.breakdown-bar-wrap {
  height: 6px;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.breakdown-bar {
  height: 100%;
  border-radius: var(--radius-full);
  transition: width var(--transition-slow);
  min-width: 4px;

  &[data-color='teal']   { background: var(--teal-500); }
  &[data-color='blue']   { background: var(--blue-500); }
  &[data-color='purple'] { background: var(--purple-500); }
}

.breakdown-weight {
  font-size: 0.65rem;
  color: var(--text-muted);
}

