import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { App } from './app';
import { routes } from './app.routes';

describe('App', () => {
  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [App],
      providers: [provideRouter(routes)],
    }).compileComponents();
  });

  it('should create the app', () => {
    const fixture = TestBed.createComponent(App);
    const app = fixture.componentInstance;
    expect(app).toBeTruthy();
  });

  it('should render the CareKaki Pro brand', async () => {
    const fixture = TestBed.createComponent(App);
    await fixture.whenStable();
    const compiled = fixture.nativeElement as HTMLElement;
    expect(compiled.textContent).toContain('CareKaki');
  });
});

const { chromium } = require('playwright-core');
const path = require('path');
const fs = require('fs');

const EDGE = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
const BASE = 'http://127.0.0.1:4200';
const OUT = process.argv[2] || path.join(__dirname, 'shots');

const routes = [
  { path: '/dashboard', name: 'dashboard' },
  { path: '/intake', name: 'intake' },
  { path: '/roster', name: 'roster' },
  { path: '/matching', name: 'matching' },
  { path: '/quotations', name: 'quotations' },
  { path: '/job-orders', name: 'job-orders' },
  { path: '/pricing', name: 'pricing' },
];

const viewports = [
  { name: 'desktop', width: 1440, height: 900, isMobile: false },
  { name: 'mobile', width: 390, height: 844, isMobile: true },
];

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({ executablePath: EDGE, headless: true });
  const errors = [];

  for (const vp of viewports) {
    const context = await browser.newContext({
      viewport: { width: vp.width, height: vp.height },
      deviceScaleFactor: 1,
      isMobile: vp.isMobile,
      hasTouch: vp.isMobile,
    });
    const page = await context.newPage();
    page.on('console', m => {
      if (m.type() === 'error') errors.push(`[${vp.name}] console: ${m.text()}`);
    });
    page.on('pageerror', e => errors.push(`[${vp.name}] pageerror: ${e.message}`));

    for (const r of routes) {
      await page.goto(BASE + r.path, { waitUntil: 'networkidle', timeout: 30000 });
      await page.waitForTimeout(900);
      const file = path.join(OUT, `${r.name}-${vp.name}.png`);
      await page.screenshot({ path: file, fullPage: true });
      console.log('saved', file);
    }
    await context.close();
  }

  await browser.close();
  console.log('\n=== PAGE ERRORS ===');
  if (errors.length === 0) console.log('none');
  else errors.forEach(e => console.log(e));
})().catch(e => { console.error('FATAL', e); process.exit(1); });

