const { chromium } = require('playwright-core');
const path = require('path');
const fs = require('fs');

const EDGE = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
const BASE = 'http://127.0.0.1:4200';
const OUT = process.argv[2] || path.join(__dirname, 'shots');

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({ executablePath: EDGE, headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  // --- Intake flow ---
  await page.goto(BASE + '/intake', { waitUntil: 'networkidle' });
  await page.getByText('Post-surgery nursing').click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: /Parse Intake/i }).click();
  await page.waitForTimeout(1800);
  const intakeText = await page.locator('.banner-title').first().textContent();
  const entityCount = await page.locator('.entity-item').count();
  console.log('INTAKE banner:', intakeText?.trim());
  console.log('INTAKE entity slots rendered:', entityCount);
  await page.screenshot({ path: path.join(OUT, 'flow-intake-parsed.png'), fullPage: true });

  // --- Matching: select + confirm ---
  await page.goto(BASE + '/matching', { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  await page.locator('.candidate-card').nth(1).click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: /Confirm Selection/i }).click();
  await page.waitForTimeout(400);
  const confirmed = await page.locator('.confirmed-msg').count();
  console.log('MATCHING confirmed state visible:', confirmed > 0);
  await page.screenshot({ path: path.join(OUT, 'flow-matching-confirmed.png'), fullPage: true });

  // --- Job order: switch to WhatsApp tab ---
  await page.goto(BASE + '/job-orders', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: /WhatsApp Dispatch/i }).click();
  await page.waitForTimeout(500);
  const bubble = await page.locator('.wa-text').count();
  console.log('JOB ORDER whatsapp bubble rendered:', bubble > 0);
  await page.screenshot({ path: path.join(OUT, 'flow-whatsapp.png'), fullPage: true });

  // --- Pricing: surcharges tab ---
  await page.goto(BASE + '/pricing', { waitUntil: 'networkidle' });
  await page.getByRole('button', { name: /Surcharges/i }).click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: path.join(OUT, 'flow-pricing-surcharges.png'), fullPage: true });

  // --- Roster: filter interaction ---
  await page.goto(BASE + '/roster', { waitUntil: 'networkidle' });
  await page.selectOption('select.filter-select >> nth=1', 'on_assignment');
  await page.waitForTimeout(400);
  const rows = await page.locator('.roster-table tbody tr').count();
  console.log('ROSTER rows after status=on_assignment filter:', rows);

  // --- Mobile drawer test ---
  const mctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  const mpage = await mctx.newPage();
  await mpage.goto(BASE + '/dashboard', { waitUntil: 'networkidle' });
  await mpage.waitForTimeout(300);
  const navVisible = await mpage.locator('.bottom-nav').isVisible();
  console.log('MOBILE bottom-nav visible:', navVisible);
  await mpage.locator('.menu-btn').click();
  await mpage.waitForTimeout(500);
  const drawerOpen = await mpage.locator('.sidebar.open').count();
  console.log('MOBILE drawer opens:', drawerOpen > 0);
  await mpage.screenshot({ path: path.join(OUT, 'flow-mobile-drawer.png') });

  await browser.close();
  console.log('\n=== ERRORS ===');
  console.log(errors.length ? errors.join('\n') : 'none');
})().catch(e => { console.error('FATAL', e); process.exit(1); });

