// --- Patient conditions ---
let conditions = '';
const condMatch = text.match(/(?:she|he|they|patient|my (?:mother|father|grandmother|grandfather|wife|husband))[^.]*?(?:had|has|needs|requires|uses|with)\s+([^.,]+)/i);
if (condMatch) {
  conditions = condMatch[1].trim();
} else if (/\b(hip replacement|dementia|alzheimer|stroke|diabetes|dialysis|wheelchair|post-surgery|palliative|mobility)\b/i.test(text)) {
  const m = text.match(/\b(hip replacement|dementia|alzheimer|stroke|diabetes|dialysis|wheelchair|post-surgery|palliative|mobility)[^.,]*/i);
  conditions = m ? m[0].trim() : '';
}
// Strip leading articles for cleaner display
conditions = conditions.replace(/^(?:a|an|the)\s+/i, '').trim();
if (!conditions) {
  conditions = 'General care and assistance required';
}

